import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
import optax
from typing import Sequence, Dict, Any

class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int; dilation: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h)
        h = nn.Conv(features=self.d_model, kernel_size=(1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class SiameseInteractionNet(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks: int; dilations: Sequence[int]
    kernel_size: int; dropout_rate: float; num_heads: int; dataset: str

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input proj and shared backbone definition
        in_proj = nn.Dense(self.d_model, name='in_proj')
        backbone_blocks = [
            DSConvDilatedBlock(self.d_model, self.kernel_size, self.dilations[i], self.dropout_rate)
            for i in range(self.num_blocks)
        ]

        # --- Input Splitting and Parallel Encoding ---
        if self.dataset == 'CRI-Off':
            x_sgrna = x[:, :23, :]
            x_target = x[:, 23:, :]
        else:
            x_sgrna = x
            x_target = jnp.zeros_like(x) # Deactivate second path

        h_sgrna = nn.gelu(in_proj(x_sgrna))
        h_sgrna = nn.Dropout(rate=self.dropout_rate)(h_sgrna, deterministic=deterministic)
        for block in backbone_blocks:
            h_sgrna = block(h_sgrna, deterministic=deterministic)

        h_target = nn.gelu(in_proj(x_target))
        h_target = nn.Dropout(rate=self.dropout_rate)(h_target, deterministic=deterministic)
        for block in backbone_blocks:
            h_target = block(h_target, deterministic=deterministic)

        # --- Interaction Modeling ---
        # Use pooled sgRNA as a query to attend to the target sequence
        q_sgrna = jnp.mean(h_sgrna, axis=1, keepdims=True) # [B, 1, C]

        attention_layer = nn.MultiHeadDotProductAttention(num_heads=self.num_heads)
        # Query is sgRNA, Key/Value is target
        interaction_vec = attention_layer(inputs_q=q_sgrna, inputs_kv=h_target)
        fused = interaction_vec.squeeze(axis=1) # [B, C]

        # --- Final MLP Head ---
        z = nn.LayerNorm()(fused)
        z = nn.Dense(self.d_model)(z)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output, name='out')(z)

        if self.task_type == 'regression' and self.d_output == 1:
            return logits.squeeze(-1)
        return logits

class SiameseWrapper:
    def __init__(self, **kwargs):
        self.network = SiameseInteractionNet(**kwargs)
    def init(self, rng_key, dummy_input):
        return self.network.init(rng_key, dummy_input, deterministic=True)['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        rngs = {'dropout': rng_key} if not deterministic else None
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs=rngs)

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 192, 'num_blocks': 5, 'dilations': [1,2,4,8,16],
        'kernel_size': 7, 'dropout_rate': 0.1, 'num_heads': 4
    }

def create_network(hparams: Dict[str, Any]):
    network_params = [
        'd_output', 'task_type', 'd_model', 'num_blocks', 'dilations',
        'kernel_size', 'dropout_rate', 'num_heads', 'dataset'
    ]
    network_hparams = {k: v for k, v in hparams.items() if k in network_params}
    return SiameseWrapper(**network_hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.01),
    )
